#include <windows.h>
DWORD QueryShellProcessId() {
    HWND shellWnd = FindWindowW(L"Progman", nullptr);
    DWORD pid = 0;
    if (shellWnd) GetWindowThreadProcessId(shellWnd, &pid);
    return pid;
}
