int InstallLocalThemeHook() {
    HMODULE mod = LoadLibraryW(L"uxtheme.dll");
    HOOKPROC fn = mod ? reinterpret_cast<HOOKPROC>(GetProcAddress(mod, "ThemeHook")) : nullptr;
    DWORD selfTid = GetCurrentThreadId();
    HHOOK hk = SetWindowsHookExW(WH_CALLWNDPROC, fn, nullptr, selfTid);
    PostThreadMessageW(selfTid, WM_NULL, 0, 0);
    if (hk) UnhookWindowsHookEx(hk);
    return 0;
}
